import pytest


def shout(xs: list[str]) -> None:
    """Print each string in xs upper-cased, one per line."""
    for s in xs:
        print(s.upper())


def test_shout_prints_uppercased_lines(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["hello", "World"])
    assert capsys.readouterr().out == "HELLO\nWORLD\n"


def test_shout_empty_list_prints_nothing(capsys: pytest.CaptureFixture[str]) -> None:
    shout([])
    assert capsys.readouterr().out == ""


def test_shout_preserves_order_and_duplicates(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["a", "b", "a"])
    assert capsys.readouterr().out == "A\nB\nA\n"


def test_shout_already_uppercase_and_empty_string(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["X", ""])
    assert capsys.readouterr().out == "X\n\n"
